    expect(renderCount).toBeLessThan(25);
  });

  it('passes a single stable composed ref to the child across re-renders', () => {
    const refIdentities = new Set<unknown>();
    let bump!: () => void;

    const Child = React.forwardRef<HTMLButtonElement>(function Child(_props, ref) {
      refIdentities.add(ref);
      return <button type="button" ref={ref} />;
    });

    function App() {
      const [, forceRender] = React.useReducer((c) => c + 1, 0);
      bump = forceRender;
      const forwardedRef = React.useRef<HTMLButtonElement>(null);
      return (
        <Slot ref={forwardedRef}>
          <Child />
        </Slot>
      );
    }

    render(<App />);
    act(() => bump());
    act(() => bump());
    expect(refIdentities.size).toBe(1);
  });

  it('passes the child ref through by identity when no forwarded ref is provided', () => {
    let receivedRef: React.Ref<HTMLButtonElement> | undefined;
    const Child = React.forwardRef<HTMLButtonElement>(function Child(_props, ref) {
      receivedRef = ref;
      return <button type="button" ref={ref} />;
    });

    const childRef = React.createRef<HTMLButtonElement>();

    render(
      <Slot>
        <Child ref={childRef} />
      </Slot>,
    );

    // No forwardedRef on <Slot/>: the child's own ref must be attached, not a composed one.
    expect(receivedRef).toBe(childRef);
    expect(childRef.current).toBeInstanceOf(HTMLButtonElement);
  });

  it('calls the child callback ref exactly once when no forwarded ref is provided', () => {
    const spy = vi.fn();

    render(
      <Slot>
        <button type="button" ref={spy}>
          Click
        </button>
      </Slot>,
    );

    expect(spy).toHaveBeenCalledTimes(1);
    expect(spy).toHaveBeenLastCalledWith(expect.any(HTMLButtonElement));
  });
});

